import json
from pathlib import Path


def _reject_non_finite(value):
    if isinstance(value, float):
        if value != value or value in (float("inf"), float("-inf")):
            raise ValueError("non-finite number in JSON payload")
    elif isinstance(value, dict):
        for v in value.values():
            _reject_non_finite(v)
    elif isinstance(value, list):
        for v in value:
            _reject_non_finite(v)


def load_payload(path):
    text = Path(path).read_text(encoding="utf-8")
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("invalid JSON payload") from exc
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level JSON must be object or array")
    _reject_non_finite(data)
    return data

import hashlib
import io
import zipfile

from .model import load_payload


def _unwrap(payload):
    # When an input object has keys exactly name/result, only its result is
    # the business input; other objects are interpreted as-is.
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    modules_payload = _unwrap(payloads[0])
    closure_payload = _unwrap(payloads[1])

    if not isinstance(modules_payload, dict) or "modules" not in modules_payload:
        raise ValueError("missing modules")
    modules = modules_payload["modules"]
    if not isinstance(modules, dict):
        raise ValueError("modules must be object")

    if not isinstance(closure_payload, dict):
        raise ValueError("closure must be object")
    paths = closure_payload.get("paths")
    external = closure_payload.get("external")
    if not isinstance(paths, list):
        raise ValueError("missing paths")
    if not isinstance(external, list):
        raise ValueError("missing external")

    # Validate paths: no duplicates, all exist in modules.
    if len(set(paths)) != len(paths):
        raise ValueError("duplicate paths")
    for p in paths:
        if p not in modules:
            raise ValueError("source path not found: %s" % p)

    # Determine whether root __init__.py is present; if missing, add empty one.
    root_init = "__init__.py"
    has_root_init = root_init in modules
    if not has_root_init:
        # Only add if the root package is actually needed (paths non-empty).
        pass

    # Build ZIP entries sorted by path.
    entries = {}
    for p in paths:
        entries[p] = modules[p]

    if not has_root_init and paths:
        entries[root_init] = ""

    sorted_paths = sorted(entries.keys())

    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_STORED) as zf:
        for p in sorted_paths:
            data = entries[p]
            if not isinstance(data, str):
                raise ValueError("module source must be string")
            raw = data.encode("utf-8")
            zi = zipfile.ZipInfo(p, date_time=(1980, 1, 1, 0, 0, 0))
            zi.create_system = 3
            zi.external_attr = 0o644 << 16
            zi.compress_type = zipfile.ZIP_STORED
            zf.writestr(zi, raw)

    zip_bytes = buf.getvalue()
    sha = hashlib.sha256(zip_bytes).hexdigest()

    return {
        "name": contract["name"],
        "result": {
            "paths": sorted_paths,
            "zip_hex": zip_bytes.hex(),
            "sha256": sha,
            "external": external,
        },
    }

import ast
from pathlib import PurePosixPath


def _norm(path):
    # normalize a relative module path to canonical form using '/'
    parts = path.replace("\\", "/").split("/")
    out = []
    for seg in parts:
        if seg in ("", "."):
            continue
        if seg == "..":
            if not out:
                raise ValueError("path escapes root")
            out.pop()
        else:
            out.append(seg)
    return "/".join(out)


def _module_name(path):
    # path like "pkg/a.py" -> "pkg.a"; "__init__.py" -> ""
    if path.endswith(".py"):
        path = path[:-3]
    parts = [p for p in path.split("/") if p]
    if parts == ["__init__"]:
        return ""
    if parts and parts[-1] == "__init__":
        parts = parts[:-1]
    return ".".join(parts)


def _resolve_relative(current_module, level, target):
    # current_module is a module name ('' for root __init__)
    if current_module == "":
        base_parts = []
    else:
        base_parts = current_module.split(".")
    if level > len(base_parts):
        raise ValueError("relative import beyond root")
    if level == 0:
        base = base_parts
    else:
        base = base_parts[: len(base_parts) - level + 1]
    if target:
        base = base + target.split(".")
    return ".".join(base)


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    raw = payloads[0]
    if isinstance(raw, dict) and set(raw) == {"name", "result"}:
        data = raw["result"]
    else:
        data = raw

    modules = data["modules"]
    entry = data["entry"]
    externals = data["externals"]
    aliases = data["aliases"]

    if entry not in modules:
        raise ValueError("entry not found")

    # build module name -> path map
    module_paths = {}
    for path in modules:
        name = _module_name(path)
        module_paths[name] = path

    imports = {}
    for path, src in modules.items():
        try:
            tree = ast.parse(src)
        except SyntaxError as e:
            raise ValueError("invalid source") from e
        deps = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    deps.add(alias.name)
            elif isinstance(node, ast.ImportFrom):
                if node.level > 0:
                    # relative import
                    current = _module_name(path)
                    target = node.module or ""
                    resolved = _resolve_relative(current, node.level, target)
                    # try X.y exists as local module
                    if resolved in module_paths:
                        deps.add(resolved)
                    else:
                        # depend on X (first segment)
                        deps.add(resolved.split(".")[0])
                else:
                    # absolute from X import y
                    mod = node.module
                    if mod is None:
                        continue
                    # try X.y exists as local module
                    candidate = mod
                    if node.names:
                        candidate = mod + "." + node.names[0].name
                    if candidate in module_paths:
                        deps.add(candidate)
                    else:
                        deps.add(mod)
        imports[path] = sorted(deps)

    return {"name": contract["name"], "result": {"imports": imports, "module_paths": module_paths}}

def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count does not match contract inputs")

    modules_payload = payloads[0]
    scan_payload = payloads[1]

    # Unwrap name/result envelope when the object keys are exactly name/result.
    def business_input(obj):
        if isinstance(obj, dict) and set(obj) == {"name", "result"}:
            return obj["result"]
        return obj

    modules = business_input(modules_payload)
    scan = business_input(scan_payload)

    if not isinstance(modules, dict) or "modules" not in modules:
        raise ValueError("missing modules")
    if not isinstance(scan, dict):
        raise ValueError("invalid scan result")

    module_map = modules["modules"]
    entry = modules["entry"]
    externals = modules.get("externals", [])
    aliases = modules.get("aliases", {})

    imports = scan.get("imports", {})
    module_paths = scan.get("module_paths", {})

    if entry not in module_map:
        raise ValueError("entry module missing")

    # Build path -> module name mapping from scan.
    path_to_name = {}
    for name, path in module_paths.items():
        path_to_name[path] = name

    def parent_packages(path):
        # Return all parent package __init__.py paths that exist.
        parts = path.split("/")
        parents = []
        for i in range(1, len(parts)):
            pkg_path = "/".join(parts[:i]) + "/__init__.py"
            if pkg_path in module_map:
                parents.append(pkg_path)
        return parents

    def is_external(name):
        if name in externals:
            return True
        first = name.split(".", 1)[0]
        return first in externals

    def resolve_alias(name):
        return aliases.get(name, name)

    # BFS over local modules.
    paths = set()
    external = set()
    queue = [entry]
    visited = set()

    while queue:
        path = queue.pop(0)
        if path in visited:
            continue
        visited.add(path)
        paths.add(path)
        for p in parent_packages(path):
            paths.add(p)

        for dep in imports.get(path, []):
            resolved = resolve_alias(dep)
            if resolved in module_paths:
                # local module
                dep_path = module_paths[resolved]
                if dep_path not in visited:
                    queue.append(dep_path)
            else:
                # external module
                if not is_external(resolved):
                    raise ValueError("unknown module: %s" % resolved)
                external.add(resolved)

    return {
        "name": contract["name"],
        "result": {
            "paths": sorted(paths),
            "external": sorted(external),
        },
    }

import json
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / "engines" / "dependencies"))

from model import load_payload
from transform import transform


class TestDependencies(unittest.TestCase):
    def test_closure(self):
        modules = {
            "main.py": "import pkg.a\n",
            "pkg/__init__.py": "from . import b\n",
            "pkg/a.py": "from . import b\nimport six.moves.urllib.parse\n",
            "pkg/b.py": "from . import a\nimport json\n",
            "unused.py": "print('unused')\n",
        }
        payload = {
            "modules": modules,
            "entry": "main.py",
            "externals": ["json", "urllib"],
            "aliases": {"six.moves.urllib.parse": "urllib.parse"},
        }
        scan = {
            "imports": {
                "main.py": ["pkg.a"],
                "pkg/__init__.py": ["pkg.b"],
                "pkg/a.py": ["pkg.b", "six.moves.urllib.parse"],
                "pkg/b.py": ["pkg.a", "json"],
            },
            "module_paths": {
                "pkg": "pkg/__init__.py",
                "pkg.a": "pkg/a.py",
                "pkg.b": "pkg/b.py",
            },
        }
        contract = {"name": "dependencies", "inputs": ["a", "b"]}
        result = transform([payload, scan], contract)
        self.assertEqual(set(result), {"name", "result"})
        self.assertEqual(result["name"], "dependencies")
        r = result["result"]
        self.assertEqual(
            r["paths"],
            ["main.py", "pkg/__init__.py", "pkg/a.py", "pkg/b.py"],
        )
        self.assertEqual(r["external"], ["json", "urllib.parse"])

    def test_unknown_module(self):
        payload = {
            "modules": {"main.py": "import missing\n"},
            "entry": "main.py",
            "externals": [],
            "aliases": {},
        }
        scan = {"imports": {"main.py": ["missing"]}, "module_paths": {}}
        contract = {"name": "dependencies", "inputs": ["a", "b"]}
        with self.assertRaises(ValueError):
            transform([payload, scan], contract)

    def test_load_payload_rejects_nan(self):
        import tempfile
        with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as f:
            f.write('{"a": NaN}')
            name = f.name
        try:
            with self.assertRaises(ValueError):
                load_payload(Path(name))
        finally:
            Path(name).unlink()


if __name__ == "__main__":
    unittest.main()

