import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _attention(components):
    names = []
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            names.append(name)
            continue
        for key in ("complete", "checkout", "committed", "ok"):
            if result.get(key) is False:
                names.append(name)
                break
        else:
            for key in ("unavailable", "missing", "conflicts", "unreachable"):
                v = result.get(key)
                if isinstance(v, (list, dict, str, tuple)) and len(v) > 0:
                    names.append(name)
                    break
    return sorted(set(names))


def main():
    core_path = ROOT / "outputs" / "core_manifest.json"
    core = json.loads(core_path.read_text(encoding="utf-8"))
    components = core["components"]

    serialized = json.dumps(
        core,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    sha256 = hashlib.sha256(serialized).hexdigest()

    report = {
        "title": "Python 支持模块发现与可重复 ZIP 载荷",
        "component_count": len(components),
        "sha256": sha256,
        "attention": _attention(components),
    }

    out = ROOT / "outputs" / "final_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()

import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _load_contracts():
    contracts = {}
    for cp in sorted(ROOT.rglob('contract.json')):
        if 'outputs' in cp.relative_to(ROOT).parts:
            continue
        c = json.loads(cp.read_text(encoding='utf-8'))
        contracts[c['name']] = (cp, c)
    return contracts


def _topological_order(contracts):
    # contracts: name -> (contract_path, contract_dict)
    names = set(contracts)
    order = []
    visited = set()
    visiting = set()

    def visit(name):
        if name in visited:
            return
        if name in visiting:
            raise ValueError('cycle in component dependencies: %s' % name)
        visiting.add(name)
        cp, c = contracts[name]
        for inp in c.get('inputs', []):
            # An input that is another component's output creates a dependency.
            for other_name, (ocp, oc) in contracts.items():
                if inp == oc.get('output'):
                    if other_name not in names:
                        raise ValueError('missing component for input %s' % inp)
                    visit(other_name)
        visiting.remove(name)
        visited.add(name)
        order.append(name)

    for name in names:
        visit(name)
    return order


def main():
    contracts = _load_contracts()
    if not contracts:
        raise ValueError('no contracts')
    order = _topological_order(contracts)
    for name in order:
        cp, c = contracts[name]
        render = cp.with_name('render.py')
        subprocess.run(
            [sys.executable, str(render)],
            cwd=ROOT,
            check=True,
            timeout=60,
        )
    subprocess.run(
        [sys.executable, str(ROOT / 'integrate.py')],
        cwd=ROOT,
        check=True,
        timeout=60,
    )


if __name__ == '__main__':
    main()

