        r = result["result"]
        self.assertEqual(r["imports"]["main.py"], ["pkg.a"])
        self.assertEqual(r["imports"]["pkg/__init__.py"], ["pkg.b"])
        self.assertEqual(r["imports"]["pkg/a.py"], ["pkg.b", "six.moves.urllib.parse"])
